INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('cf5b6d09-3365-565c-941d-19b0f52aacce', '371fce26-d1f3-439b-95df-0a0e38b8a824', '952afcf1-59a1-5ab2-80fc-459d97323fe0', NULL, NULL, 'Inside a band, each stage takes its own stretch of the band''s teaching time, in dependency order. Stages with no dependency between them are ordered by strand and then by id.', 'derived', 'low', 'Design note 2026-10-25, section 5.11 (order checks).', 'The prerequisite and foundational links between strands apply inside each grade band. This is a rule of the model and makes no claim about how any school should sequence.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('5ae14b19-7e3d-5898-9068-13ec6edf85c8', '371fce26-d1f3-439b-95df-0a0e38b8a824', '2b600783-7c8d-5914-8529-53cf6945c19d', NULL, NULL, 'This plan reverses the dependency order on purpose. It is a negative control for the order check and carries no design intent.', 'derived', 'high', 'Design note 2026-10-25, section 5.11.', 'A check that never reports a violation tells us little. The control shows what a violation looks like on this space.', NULL) ON CONFLICT (id) DO NOTHING;

